def solve():
    rows, cols = 20, 19

    grid = [[0]*cols for _ in range(rows)]

    # For nested rectangles, we want to avoid overlaps. 
    # Each region has margins relative to inner regions.
    # Strategy: calculate each cell's value based on which region it belongs to

    # Region boundaries (inclusive):
    # 6: r[0-9], c[0-18] but excluding inner regions
    # 8: r[1-8], c[1-17] but excluding inner  
    # ... etc

    def get_color(r, c):
        # Check which region this cell belongs to (outermost to innermost)
        # Return first matching region's color

        # Check all possible concentric regions
        if r <= 9 and r >= 0 and c <= 18 and c >= 0:
            # Inside outermost region
            if r <= 8 and r >= 1 and c <= 17 and c >= 1:
                if r <= 7 and r >= 2 and c <= 16 and c >= 2:
                    if r <= 6 and r >= 3 and c <= 15 and c >= 3:
                        if r <= 5 and r >= 4 and c <= 14 and c >= 4:
                            if r == 4 and c == 9:
                                return 3
                            else:
                                return 4
                        else:
                            return 2
                    else:
                        return 8
                else:
                    return 6
            else:
                return 6
        else:
            return 0

    result = []
    for r in range(rows):
        row = []
        for c in range(cols):
            row.append(get_color(r, c))
        result.append(row)

    return result

